<script setup lang="ts">type Row={id:string;name:string;slug:string;description:string|null;color?:string|null;coverUrl?:string|null;parentId?:string|null;position?:number;seoTitle?:string|null;seoDescription?:string|null;_count?:{posts:number;children?:number}};const props=defineProps<{kind:'categories'|'tags';title:string}>();const {data,refresh}=await useFetch<Row[]>(`/api/admin/${props.kind}`);const csrf=useCsrf();const editing=ref<Row|null>(null);const open=ref(false);const q=ref('');const model=reactive({name:'',slug:'',description:'',color:'#d75a32',coverUrl:'',parentId:'',position:0,seoTitle:'',seoDescription:''});watch(q,async v=>{if(props.kind==='tags')data.value=await $fetch<Row[]>(`/api/admin/tags?q=${encodeURIComponent(v)}`)});function start(row?:Row){editing.value=row||null;open.value=true;Object.assign(model,{name:row?.name||'',slug:row?.slug||'',description:row?.description||'',color:row?.color||'#d75a32',coverUrl:row?.coverUrl||'',parentId:row?.parentId||'',position:row?.position||0,seoTitle:row?.seoTitle||'',seoDescription:row?.seoDescription||''})}async function save(){const body={...model,parentId:model.parentId||null,coverUrl:model.coverUrl||undefined};await $fetch(editing.value?`/api/admin/${props.kind}/${editing.value.id}`:`/api/admin/${props.kind}`,{method:editing.value?'PUT':'POST',headers:csrf.value,body});open.value=false;await refresh()}async function remove(row:Row){if(!confirm(`删除“${row.name}”？`))return;try{await $fetch(`/api/admin/${props.kind}/${row.id}`,{method:'DELETE',headers:csrf.value});await refresh()}catch(e){alert((e as {data?:{message?:string}}).data?.message||'删除失败')}}</script><template><div><div class="flex justify-between"><h1 class="text-3xl font-semibold">{{title}}</h1><button class="rounded-full px-5 py-2 text-white" style="background:var(--accent)" @click="start()">新建</button></div><input v-if="kind==='tags'" v-model="q" class="mt-5 rounded-lg border bg-transparent p-3" placeholder="搜索名称或 Slug"><div class="mt-5 grid gap-3"><article v-for="row in data||[]" :key="row.id" class="flex items-center justify-between rounded-xl border p-4" style="border-color:var(--border)"><div><strong>{{row.name}}</strong><span class="ml-2 text-xs" style="color:var(--muted)">{{row.slug}} · {{row._count?.posts||0}} 篇文章</span><p>{{row.description}}</p></div><div class="flex gap-3"><button @click="start(row)">编辑</button><button @click="remove(row)">删除</button></div></article></div><div v-if="open" class="fixed inset-0 z-50 grid place-items-center bg-black/50 p-4" @click.self="open=false"><form class="w-full max-w-xl rounded-2xl p-6" style="background:var(--surface)" @submit.prevent="save"><h2 class="text-xl font-semibold">{{editing?'编辑':'新建'}}{{title}}</h2><div class="mt-4 grid gap-3"><input v-model="model.name" required placeholder="名称" class="rounded border bg-transparent p-2"><input v-model="model.slug" required placeholder="slug" class="rounded border bg-transparent p-2"><textarea v-model="model.description" placeholder="描述" class="rounded border bg-transparent p-2"/><input v-if="kind==='tags'" v-model="model.color" type="color"><template v-if="kind==='categories'"><select v-model="model.parentId" class="rounded border bg-transparent p-2"><option value="">顶级分类</option><option v-for="c in data||[]" :key="c.id" :value="c.id" :disabled="c.id===editing?.id">{{c.name}}</option></select><input v-model.number="model.position" type="number" placeholder="顺序" class="rounded border bg-transparent p-2"><input v-model="model.coverUrl" placeholder="封面 URL" class="rounded border bg-transparent p-2"></template><input v-model="model.seoTitle" placeholder="SEO 标题" class="rounded border bg-transparent p-2"><input v-model="model.seoDescription" placeholder="SEO 描述" class="rounded border bg-transparent p-2"></div><div class="mt-5 flex justify-end gap-3"><button type="button" @click="open=false">取消</button><button class="rounded-lg px-4 py-2 text-white" style="background:var(--accent)">保存</button></div></form></div></div></template>
